package com.hbm.missile.completion.volcano;
import com.hbm.hazard.HbmHazards;import java.util.List;import net.minecraft.ChatFormatting;import net.minecraft.network.chat.Component;import net.minecraft.world.item.*;
public final class VolcanoItem extends BlockItem {public VolcanoItem(VolcanoBlock block){super(block,new Properties().component(HbmHazards.LEGACY_METADATA.get(),0));}@Override public void appendHoverText(ItemStack stack,TooltipContext context,List<Component> lines,TooltipFlag flag){int meta=stack.getOrDefault(HbmHazards.LEGACY_METADATA.get(),0);if(meta==4){lines.add(Component.translatable("tooltip.hbm.volcano.shield").withStyle(ChatFormatting.GOLD));return;}boolean growing=VolcanoBlock.growing(meta),extinguishing=VolcanoBlock.extinguishing(meta);lines.add(Component.translatable(growing?"tooltip.hbm.volcano.grows":"tooltip.hbm.volcano.static").withStyle(growing?ChatFormatting.RED:ChatFormatting.DARK_GRAY));lines.add(Component.translatable(extinguishing?"tooltip.hbm.volcano.extinguishes":"tooltip.hbm.volcano.persistent").withStyle(extinguishing?ChatFormatting.RED:ChatFormatting.DARK_GRAY));}}
